#!/bin/sh
# Generated by seaworthy: acme-agent, deb, after removal. See seaworthy::scripts.
set -e
systemd_running() { [ -d /run/systemd/system ]; }
has_systemctl() { [ -z "${DPKG_ROOT:-}" ] && command -v systemctl >/dev/null 2>&1; }
try() { "$@" || echo "acme-agent: warning: '$*' failed (exit $?); continuing" >&2; }
action=none
case "${1:-}" in
  remove|purge) action=remove ;;
  abort-install) action=restore ;;
esac
if [ "$action" != none ]; then rm -f /run/seaworthy/acme-agent.new-units; fi
if [ "$action" = remove ] && has_systemctl && systemd_running; then
  try systemctl daemon-reload
fi
